              function format_applicant_followers($num) {
                  $n = (float)$num;
                  if ($n >= 1000000) {
                      return round($n / 1000000, 1) . 'M';
                  } elseif ($n >= 1000) {
                      return round($n / 1000, 1) . 'K';
                  }
                  return number_format($n);
              }
